{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Scale history item embeddings by 1 + 0.1*tanh(z), with z the standardized log1p frequency computed solely from each category's training interactions. Keep padding zero and candidate embeddings unchanged. Store the fixed feature as a checkpoint buffer; the existing predictor writer imports the updated SASRec class and restores that buffer. Learned embeddings, Transformer topology, readout, loss, optimizer, seeds and epoch binding remain unchanged.",
      "edits": [
        {
          "find": "DATA_DIR = os.environ.get(\"GAGC_DATA_DIR\", \"./input/trainval\")",
          "replace": "DATA_DIR = os.environ['GAGC_DATA_DIR']"
        },
        {
          "find": "        self.itemnum = itemnum\n\n        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)",
          "replace": "        self.itemnum = itemnum\n\n        self.register_buffer(\"history_frequency_scale\", torch.ones(itemnum + 1))\n        self.history_frequency_scale[0] = 0.0\n\n        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)"
        },
        {
          "find": "        seq_emb = self.item_emb(seq) * (self.hidden_units ** 0.5)",
          "replace": "        seq_emb = self.item_emb(seq) * (self.hidden_units ** 0.5)\n        seq_emb = seq_emb * self.history_frequency_scale[seq].unsqueeze(-1)"
        },
        {
          "find": "    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY, betas=(0.9, 0.98))",
          "replace": "    # Fixed input feature computed exclusively from this category's training split.\n    frequency = np.zeros(itemnum + 1, dtype=np.float64)\n    for history in user_train.values():\n        np.add.at(frequency, np.asarray(history, dtype=np.int64), 1.0)\n    log_frequency = np.log1p(frequency[1:])\n    standardized = (log_frequency - log_frequency.mean()) / max(float(log_frequency.std()), 1e-8)\n    history_scale = np.zeros(itemnum + 1, dtype=np.float32)\n    history_scale[1:] = 1.0 + 0.1 * np.tanh(standardized)\n    with torch.no_grad():\n        model.history_frequency_scale.copy_(\n            torch.as_tensor(history_scale, device=device)\n        )\n\n    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY, betas=(0.9, 0.98))"
        }
      ]
    }
  ],
  "change_summary": "Add a bounded training-frequency feature to history inputs, persisted in each category's single checkpoint and restored automatically by the generated predictor."
}
